def calcular_media(valores):
    if not valores:
        return 'lista vazia'
    total = sum(valores)
    return total / len(valores)

assert calcular_media([1, 2, 3]) == 2.0
assert calcular_media([10, 10]) == 10.0
assert calcular_media([-3, 3]) == 0.0
assert calcular_media([]) == 'lista vazia'
assert calcular_media([5]) == 5.0

